     1	import java.math.BigDecimal;
     2	import java.math.RoundingMode;
     3	import java.util.List;
     4	
     5	public class ClaimOffice {
     6	
     7	    private static final int PROCESSING_FEE_IN_G = 5;
     8	
     9	    private final PolicyWideModifiers policyWideModifiers;
    10	
    11	    public ClaimOffice(Customer customer) {
    12	        this.policyWideModifiers = new PolicyWideModifiers(customer);
    13	    }
    14	
    15	    /**
    16	     * The policy base premium is the sum of the base premiums of the main items
    17	     * and of the components, each priced by its own MHPCO pricing policy.
    18	     *
    19	     * The MHPCO names this amount in its own rules, so it is observable inside
    20	     * the domain; it is not part of what the office offers a caller, which is
    21	     * a quote.
    22	     */
    23	    int basePremium(List<Item> items) {
    24	        return MainItemPricing.mainItemsBasePremium(items)
    25	                + ComponentPricing.componentsBasePremium(items);
    26	    }
    27	
    28	    /**
    29	     * Item-specific modifiers apply to the base premium of the affected item,
    30	     * not to the policy total.
    31	     */
    32	    BigDecimal premiumAfterItemModifiers(List<Item> items) {
    33	        return BigDecimal.valueOf(basePremium(items))
    34	                .add(ItemRiskSurcharges.totalItemSurcharges(items));
    35	    }
    36	
    37	    /**
    38	     * The MHPCO assembles a premium in a fixed order: the policy base premium,
    39	     * then the item-specific risk surcharges, then the policy-wide modifiers,
    40	     * and the processing fee at the very end.
    41	     */
    42	    public int quote(List<Item> items) {
    43	        BigDecimal quotedPremium = premiumAfterItemModifiers(items)
    44	                .add(policyWideModifiers.totalPolicyModifiers(
    45	                        BigDecimal.valueOf(basePremium(items))))
    46	                .add(BigDecimal.valueOf(PROCESSING_FEE_IN_G));
    47	        policyWideModifiers.recordContractIssued();
    48	        return roundedInTheMhpcoFavour(quotedPremium);
    49	    }
    50	
    51	    /**
    52	     * All amounts are rounded to whole G in the MHPCO's favour: a premium the
    53	     * customer owes is rounded up.
    54	     */
    55	    private static int roundedInTheMhpcoFavour(BigDecimal premium) {
    56	        return premium.setScale(0, RoundingMode.CEILING).intValueExact();
    57	    }
    58	}
