     * All amounts are rounded to whole G in the MHPCO's favour: a premium the
     * customer owes is rounded up.
     */
    private static int roundedInTheMhpcoFavour(BigDecimal premium) {
        return premium.setScale(0, RoundingMode.CEILING).intValueExact();
    }
